CREATE TABLE assessment_scales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, name varchar(80) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assessment_scale_options (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, scale_id uuid NOT NULL REFERENCES assessment_scales(id) ON DELETE CASCADE, code varchar(20) NOT NULL, label varchar(80) NOT NULL, position smallint NOT NULL, UNIQUE(scale_id, code), UNIQUE(scale_id, position));
CREATE TABLE assessment_frameworks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, scale_id uuid NOT NULL REFERENCES assessment_scales(id), name varchar(120) NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE development_areas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, framework_id uuid NOT NULL REFERENCES assessment_frameworks(id) ON DELETE CASCADE, name varchar(120) NOT NULL, position smallint NOT NULL, UNIQUE(framework_id, position));
CREATE TABLE sub_areas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, development_area_id uuid NOT NULL REFERENCES development_areas(id) ON DELETE CASCADE, name varchar(120) NOT NULL, position smallint NOT NULL, UNIQUE(development_area_id, position));
CREATE TABLE indicators (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, sub_area_id uuid NOT NULL REFERENCES sub_areas(id) ON DELETE CASCADE, description text NOT NULL, position smallint NOT NULL, UNIQUE(sub_area_id, position));
CREATE TABLE student_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, semester_id uuid NOT NULL REFERENCES semesters(id) ON DELETE CASCADE, indicator_id uuid NOT NULL REFERENCES indicators(id) ON DELETE CASCADE, scale_option_id uuid NOT NULL REFERENCES assessment_scale_options(id), assessed_by uuid NOT NULL REFERENCES users(id), assessed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(student_id, semester_id, indicator_id));
CREATE INDEX idx_student_assessments_workspace ON student_assessments(school_id, student_id, semester_id);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['assessment_scales','assessment_scale_options','assessment_frameworks','development_areas','sub_areas','indicators','student_assessments'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY %I ON %I USING (school_id = NULLIF(current_setting(''app.school_id'', true), '''')::uuid) WITH CHECK (school_id = NULLIF(current_setting(''app.school_id'', true), '''')::uuid)',t||'_isolation',t); END LOOP; END $$;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO ramu_app;
